import { Effect, Schema } from "effect";
import { AIError, HttpOptions, InvalidRequestError, ModelID, ProviderID, ProviderMetadata, Usage, } from "../schema/index.js";
import { EvaluationClient, Service } from "./evaluation-client.js";
export const EvaluationInput = Schema.Union([Schema.String, Schema.JsonObject, Schema.Array(Schema.Json)]);
const EvaluationCriterion = Schema.NullOr(EvaluationInput);
const ChoiceCriteria = Schema.Record(Schema.String, EvaluationCriterion).pipe(Schema.refine((x) => Object.keys(x).length > 0, {
    message: "Choice criteria must be a nonempty option map",
}));
export const ChoiceQuestion = Schema.Struct({
    type: Schema.Literal("choice"),
    instructions: EvaluationInput,
    criteria: ChoiceCriteria,
});
export const ScoreQuestion = Schema.Struct({
    type: Schema.Literal("score"),
    instructions: EvaluationInput,
    criteria: Schema.Array(EvaluationCriterion).check(Schema.isMinLength(2)),
});
export const BooleanQuestion = Schema.Struct({
    type: Schema.Literal("boolean"),
    instructions: EvaluationInput,
    criteria: Schema.optional(Schema.Struct({
        true: Schema.optional(EvaluationCriterion),
        false: Schema.optional(EvaluationCriterion),
    })),
});
export const EvaluationQuestion = Schema.Union([ChoiceQuestion, ScoreQuestion, BooleanQuestion]).pipe(Schema.toTaggedUnion("type"));
const EvaluationQuestions = Schema.Record(Schema.String, EvaluationQuestion).pipe(Schema.refine((x) => Object.keys(x).length > 0, {
    message: "Evaluation questions must be a nonempty map",
}));
const Probability = Schema.Number.check(Schema.isBetween({ minimum: 0, maximum: 1 }));
export const ChoiceAnswer = Schema.Struct({
    type: Schema.Literal("choice"),
    choice: Schema.String,
    probabilities: Schema.optional(Schema.Record(Schema.String, Probability)),
    confidence: Schema.optional(Probability),
});
export const ScoreAnswer = Schema.Struct({
    type: Schema.Literal("score"),
    score: Schema.Number,
    probabilities: Schema.optional(Schema.Record(Schema.String, Probability)),
    confidence: Schema.optional(Probability),
});
export const BooleanAnswer = Schema.Struct({
    type: Schema.Literal("boolean"),
    probability: Probability,
});
export const EvaluationAnswer = Schema.Union([ChoiceAnswer, ScoreAnswer, BooleanAnswer]).pipe(Schema.toTaggedUnion("type"));
export class EvaluationModel {
    id;
    provider;
    route;
    http;
    constructor(input) {
        this.id = input.id;
        this.provider = input.provider;
        this.route = input.route;
        this.http = input.http;
    }
    static make(input) {
        return new EvaluationModel({
            id: ModelID.make(input.id),
            provider: ProviderID.make(input.provider),
            route: input.route,
            http: input.http,
        });
    }
}
export const EvaluationModelSchema = Schema.declare((value) => value instanceof EvaluationModel, {
    expected: "Evaluation.Model",
});
export class EvaluationRequest extends Schema.Class("Evaluation.Request")({
    model: EvaluationModelSchema,
    state: EvaluationInput,
    questions: EvaluationQuestions,
    options: Schema.optional(Schema.Record(Schema.String, Schema.Unknown)),
    http: Schema.optional(HttpOptions),
}) {
}
export class EvaluationRounding extends Schema.Class("Evaluation.Rounding")({
    probabilityDecimals: Schema.optional(Schema.Int),
    scoreDecimals: Schema.optional(Schema.Int),
}) {
}
export class EvaluationResponse extends Schema.Class("Evaluation.Response")({
    model: ModelID,
    answers: Schema.Record(Schema.String, EvaluationAnswer),
    usage: Schema.optional(Usage),
    rounding: Schema.optional(EvaluationRounding),
    providerMetadata: Schema.optional(ProviderMetadata),
}) {
}
export function request(input) {
    if (input instanceof EvaluationRequest)
        return input;
    return new EvaluationRequest({
        ...input,
        model: input.model,
        http: HttpOptions.make(input.http),
    });
}
export function run(input) {
    return Effect.try({
        try: () => (input instanceof EvaluationRequest ? input : request(input)),
        catch: (cause) => new AIError({
            reason: new InvalidRequestError({
                message: cause instanceof Error ? cause.message : String(cause),
                cause,
            }),
        }),
    }).pipe(Effect.flatMap((request) => EvaluationClient.evaluate(request)));
}
export const Evaluation = {
    request,
    run,
};
